INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('leitura-combate', 'Uma vez por turno, ao errar um ataque, recebe +2 na próxima jogada de ataque contra o mesmo alvo até o fim do turno.', 0);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('leitura-combate', 'Se acertar esse ataque, o alvo recebe uma penalidade de -2 na próxima jogada de ataque contra você.', 1);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('passo-calculado', 'Ao se mover metade do seu deslocamento ou menos no turno, recebe +2 na CA até o início do próximo turno.', 0);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('passo-calculado', 'Esse bônus não se aplica se estiver com armadura pesada.', 1);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('sobrevivente-nato', 'Recebe +2 em testes de resistência contra exaustão.', 0);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('sobrevivente-nato', 'Pode passar o dobro do tempo normal sem comida ou água antes de sofrer penalidades.', 1);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('sobrevivente-nato', 'Testes para rastrear você têm CD aumentada em +2.', 2);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('reacao-instintiva', 'Adiciona o seu bônus de proficiência em testes de Iniciativa.', 0);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('reacao-instintiva', 'Na primeira rodada de combate, se ainda não tiver agido, recebe um bônus na CA igual ao seu bônus de proficiência.', 1);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('foco-disciplinado', 'Recebe +2 em testes de Constituição para manter concentração.', 0);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('foco-disciplinado', 'Ao falhar por 2 ou menos, pode repetir o teste mais uma única vez.', 1);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('leitor-intencoes', '+1 em Sabedoria (máx. 20).', 0);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('leitor-intencoes', '+5 em testes de Intuição para detectar mentiras.', 1);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('olhar-analitico', 'Ação bônus: escolha uma criatura a até 12 m e realize um teste de Intuição (CD = 10 + metade do CR da criatura ou 10 + mod. de Enganação do alvo).', 0);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('olhar-analitico', 'Em sucesso, você descobre uma resistência, imunidade ou vulnerabilidade da criatura (à escolha do mestre).', 1);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('olhar-analitico', 'Em um sucesso por 5 ou mais, pode escolher qual dessas informações deseja saber.', 2);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('improvisador', 'Você pode usar um kit de ferramentas diferente do necessário; a rolagem é feita com desvantagem.', 0);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('improvisador', 'Você recebe proficiência em um kit de ferramenta à sua escolha.', 1);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('improvisador', 'Você consome metade do material em produção.', 2);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('planejador-nato', 'Após 1 minuto de planejamento, escolha até 6 criaturas aliadas.', 0);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('planejador-nato', 'Cada uma pode adicionar 1d6 a uma única jogada de ataque, teste de habilidade ou resistência nas próximas 1 hora.', 1);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('planejador-nato', 'Uma criatura só pode se beneficiar uma vez por uso deste talento.', 2);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('planejador-nato', 'Pode usar essa habilidade uma vez por descanso curto ou longo.', 3);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('mente-inabalavel', '+2 em testes de resistência contra ser Amedrontado ou Enfeitiçado.', 0);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('mente-inabalavel', 'Reação: ao falhar em um teste contra esses efeitos, pode repetir o teste.', 1);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('mente-inabalavel', 'Em sucesso, torna-se imune ao mesmo efeito pela duração original.', 2);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('mente-inabalavel', 'Pode usar essa reação uma vez por descanso curto.', 3);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('intervencao-rapida', 'Reação: quando um aliado a até 1,5 m falhar em um teste de habilidade ou resistência, você pode conceder +1d6 ao resultado.', 0);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('intervencao-rapida', 'Se isso transformar a falha em sucesso, o aliado pode se mover até 3 m sem provocar ataques de oportunidade.', 1);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('intervencao-rapida', 'Pode usar essa reação um número de vezes igual ao bônus de proficiência por descanso longo.', 2);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('momentos-heroicos', '+1 em Constituição (máx. 20).', 0);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('momentos-heroicos', 'No momento que você for levado a 0 pontos de vida, você pode usar sua reação para realizar uma ação completa.', 1);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('momentos-heroicos', 'Você pode usar essa habilidade uma vez por descanso longo.', 2);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('adaptado-a-noite', '+1 em Sabedoria (máx. 20).', 0);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('adaptado-a-noite', 'Você adquire visão no escuro de 9 m, ou aumenta em 9 m se já possuir.', 1);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('adaptado-a-noite', 'Você não sofre desvantagem em qualquer teste de perícia realizado na escuridão total.', 2);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('adaptado-a-noite', 'Recebe +2 em testes contra exaustão causada por falta de descanso.', 3);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('sentido-sismico', '+1 em Sabedoria (máx. 20).', 0);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('sentido-sismico', 'Enquanto estiver cego ou de olhos fechados, você possui visão sísmica em 9 m.', 1);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('especialista-anatomia', 'Escolha dois tipos de criatura.', 0);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('especialista-anatomia', 'Seus ataques contra esses tipos são críticos com 19–20.', 1);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('especialista-anatomia', 'Ao realizar um acerto crítico, adiciona seu modificador de Inteligência ou Sabedoria ao dano.', 2);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('especialista-anatomia', 'Recebe +2 em testes para recordar informações sobre esses tipos.', 3);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('ataque-preciso', 'Quando tiver vantagem em ataques, rola 3 dados em vez de 2.', 0);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('ataque-preciso', 'Se tiver vantagem, seu crítico ocorre com 19–20.', 1);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('valentao', 'Sempre que você causar dano a uma criatura com ND menor que metade do seu nível, causa 1d10 de dano extra.', 0);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('valentao', 'Se o ND for menor que um quarto do seu nível, causa 2d10 de dano extra.', 1);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('afortunado', 'Rolagens de d100 envolvendo encontros ou tesouros que afetem você são feitas duas vezes, escolhendo o melhor resultado.', 0);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('vicio-apostas', 'No início de cada turno, role 1d20.', 0);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('vicio-apostas', 'Resultado par: +2 em ataques, testes e resistências até o próximo turno.', 1);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('vicio-apostas', 'Resultado ímpar: –1 nessas rolagens.', 2);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('vicio-apostas', '20: bônus se torna +3.', 3);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('vicio-apostas', '1: penalidade se torna –2.', 4);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('multi-tarefa', 'Você pode realizar duas ações no turno, desde que nenhuma seja Ataque ou conjuração de magia.', 0);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('multi-tarefa', 'Pode usar essa habilidade uma vez por descanso curto.', 1);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('mestre-alquimia', 'Ganha proficiência com kit de alquimia.', 0);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('mestre-alquimia', 'Duração de poções criadas por você é multiplicada pelo bônus de proficiência.', 1);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('mestre-alquimia', 'Pode gastar um uso extra do kit para rolar testes de fabricação com vantagem.', 2);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('mestre-ferreiro', 'Ganha proficiência com ferramentas de ferreiro.', 0);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('mestre-ferreiro', 'Itens criados por você possuem +1 em testes relacionados à sua função.', 1);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('mestre-ferreiro', 'Você reduz o custo de criação de itens metálicos em 25%.', 2);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('capitalista', '+1 em Carisma (máx. 20).', 0);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('capitalista', 'Ao rolagar um teste de Persuasão ou Enganação para obter lucro financeiro, role 1d6 e adicione ao teste.', 1);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('capitalista', 'Ao administrar um negócio, aumente os ganhos em 25% ou reduza os custos em 25%', 2);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('evasivo', 'Ao usar Esquiva, recebe bônus de CA igual ao bônus de proficiência.', 0);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('evasivo', 'Recebe +2 em testes de resistência de Destreza enquanto estiver esquivando.', 1);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('evasivo', 'Reação: reduz pela metade dano que permitir teste de Destreza para metade.', 2);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('explorador-masmorras', '+1 em Sabedoria (máx. 20).', 0);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('explorador-masmorras', 'Você e até 6 aliados não se perdem em masmorras.', 1);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('explorador-masmorras', 'Aliados a até 3 m recebem +2 em Percepção, Investigação e Sobrevivência para detectar armadilhas e caminhos.', 2);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('explorador-masmorras', 'Luz fraca é tratada como luz plena para você.', 3);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('ossos-de-colosso', 'Reduz todo dano físico (Concutente, Perfurante e Cortante) recebido em valor igual ao bonus de proficiencia.', 0);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('resistencia-sob-pressao', 'Enquanto estiver com menos da metade dos PV, recebe +2 na CA.', 0);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('resistencia-sob-pressao', 'Recebe +2 em testes de resistência.', 1);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('equilibrio-perfeito', 'Não pode ser derrubado enquanto estiver consciente, a menos que fique incapacitado.', 0);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('equilibrio-perfeito', 'Recebe +2 na CA contra ataques feitos com vantagem.', 1);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('reserva-arcana', 'Ganha um espaço de magia adicional do menor nível disponível.', 0);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('reserva-arcana', 'Uma vez por descanso longo, pode recuperar um espaço de magia gasto como ação bônus.', 1);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('explosao-controlada', 'Magias de área podem excluir um número de criaturas igual ao seu bonus de proficiência.', 0);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('explosao-controlada', 'Criaturas excluídas não sofrem dano nem efeitos.', 1);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('conjuracao-economica', 'Quando uma magia requer componentes verbais e somáticos, você pode ignorar um dos dois à sua escolha.', 0);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('conjuracao-economica', 'Uma vez por descanso longo, ao conjurar uma magia, pode tratar o seu custo em espaços de magia como se fosse de um nível inferior (mínimo 1º nível).', 1);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('ancora-arcana', 'Criaturas têm desvantagem em testes para dissipar ou encerrar suas magias.', 0);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('ancora-arcana', 'Se sua concentração for quebrada, o efeito da magia persiste até o final do turno atual.', 1);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('alcance-flexivel', 'Uma vez por turno, pode aumentar ou reduzir pela metade o alcance de uma magia.', 0);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('alcance-flexivel', 'Magias de toque podem ser conjuradas a até 3 m.', 1);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('retencao-magica', 'Ao preparar uma ação para conjurar magia, não precisa manter concentração até o gatilho ocorrer.', 0);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('retencao-magica', 'Se o gatilho não ocorrer, você não perde o espaço de magia.', 1);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('contrafluxo', 'Reação: quando uma criatura a até 9 m conjurar uma magia que você tenha preparada, você recebe +2 no próximo teste de resistência contra magia até o fim do turno.', 0);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('contrafluxo', 'Se passar no teste, pode mover-se 3 m sem provocar ataques de oportunidade.', 1);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('estabilidade-ritual', 'Tempo adicional para conjurar rituais é reduzido pela metade.', 0);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('estabilidade-ritual', 'Você não pode ser interrompido durante um ritual, a menos que fique incapacitado.', 1);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('eco-defensivo', 'Após conjurar uma magia de 1º nível ou superior, recebe +1 na CA até o início do próximo turno.', 0);
INSERT INTO talento_beneficios (talento_id, texto, ordem) VALUES ('eco-defensivo', 'Se a magia exigir concentração, o bônus aumenta para +2 até o início do seu próximo turno.', 1);